import{_ as d,I as g,c as h,o as a,a3 as l,b as r,w as e,a as i,J as n,a4 as o}from"./chunks/framework.BusRvirq.js";const B=JSON.parse('{"title":"엠파시 사업 및 개발 방법론 종합 포털","description":"소프트웨어 사업의 출발점인 사전영업(RFP 분석)부터 계약, 행정, AI-SDLC, 122종 표준 산출물 납품, 감리, 상용 오픈 및 대금 회수에 이르는 전 생애주기를 체계화한 엠파시 표준 엔터프라이즈 사업 운영 및 개발 방법론 포털입니다.","frontmatter":{"title":"엠파시 사업 및 개발 방법론 종합 포털","description":"소프트웨어 사업의 출발점인 사전영업(RFP 분석)부터 계약, 행정, AI-SDLC, 122종 표준 산출물 납품, 감리, 상용 오픈 및 대금 회수에 이르는 전 생애주기를 체계화한 엠파시 표준 엔터프라이즈 사업 운영 및 개발 방법론 포털입니다.","head":[["meta",{"name":"keywords","content":"엠파시 방법론, 사업 및 개발 방법론, 소프트웨어 사업 운영, RFP 분석, 기술 제안서, 착수계, WBS, 122종 표준 서식, AI-SDLC, UAT, 최종 검수, SLA, 엠파시, Empasy"}],["meta",{"property":"og:title","content":"엠파시 사업 및 개발 방법론 종합 포털"}],["meta",{"property":"og:description","content":"수주부터 오픈 및 정산까지 전 주기를 관통하는 엠파시 공식 사업 및 개발 방법론"}],["meta",{"property":"og:image","content":"https://doc.empasy.com/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/methodology/"}],["link",{"rel":"canonical","href":"https://doc.empasy.com/methodology/"}]],"sort":80},"headers":[],"relativePath":"methodology/index.md","filePath":"ko/methodology/index.md","lastUpdated":1790906401000}'),p={name:"methodology/index.md"};function A(c,t,m,f,E,P){const s=g("Mermaid");return a(),h("div",null,[t[2]||(t[2]=l('<h1 id="엠파시-사업-및-개발-방법론-종합-포털" tabindex="-1">엠파시 사업 및 개발 방법론 종합 포털 <a class="header-anchor" href="#엠파시-사업-및-개발-방법론-종합-포털" aria-label="Permalink to “엠파시 사업 및 개발 방법론 종합 포털”">​</a></h1><p><strong>엠파시 사업 및 개발 방법론 (Empasy Business &amp; Development Methodology)</strong>은 소프트웨어 사업의 출발점인 <strong>제안요청서(RFP) 분석 및 사전영업(Pre-sales)</strong>부터 <strong>계약 체결, 착수, 명세 우선 아키텍처 설계, 에이전트 협업 구현, 품질 검증 및 감리, 상용 오픈, 최종 검수 서명, 잔금 회수 및 1년 무상 하자보수</strong>에 이르는 전 생애주기를 체계화한 전사 표준 엔터프라이즈 사업 운영 및 개발 방법론입니다.</p><p>본 포털은 회사 경영진, 영업대표, 총괄PM, 아키텍트, 개발자, QA 엔지니어, 경영지원 부서, 그리고 고객사(발주처) 의사결정권자에 이르기까지 프로젝트에 참여하는 모든 이해관계자가 자신의 책임을 명확히 인지하고 즉시 실무에 투입될 수 있도록 구성된 종합 실무 허브입니다.</p><hr><h2 id="_1-방법론-4대-핵심-체계" tabindex="-1">1. 방법론 4대 핵심 체계 <a class="header-anchor" href="#_1-방법론-4대-핵심-체계" aria-label="Permalink to “1. 방법론 4대 핵심 체계”">​</a></h2>',5)),(a(),r(o,null,{default:e(()=>[n(s,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20CorePillars%20%5B%22%EC%97%A0%ED%8C%8C%EC%8B%9C%20%EC%82%AC%EC%97%85%20%EB%B0%8F%20%EA%B0%9C%EB%B0%9C%20%EB%B0%A9%EB%B2%95%EB%A1%A0%204%EB%8C%80%20%EA%B8%B0%EB%91%A5%22%5D%0A%20%20%20%20%20%20%20%20P1%5B%221.%20%EC%82%AC%EC%97%85%20%EB%B0%8F%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EA%B4%80%EB%A6%AC%3Cbr%2F%3E(Business%20%26%20PM%20Governance)%22%5D%0A%20%20%20%20%20%20%20%20P2%5B%222.%20AI%20%EA%B0%9C%EB%B0%9C%20%EC%83%9D%EB%AA%85%EC%A3%BC%EA%B8%B0%3Cbr%2F%3E(Empasy%20AI-SDLC)%22%5D%0A%20%20%20%20%20%20%20%20P3%5B%223.%20%ED%91%9C%EC%A4%80%20%EC%82%B0%EC%B6%9C%EB%AC%BC%20%26%20122%EC%A2%85%20%EC%84%9C%EC%8B%9D%3Cbr%2F%3E(Deliverables%20Suite)%22%5D%0A%20%20%20%20%20%20%20%20P4%5B%224.%20%EC%95%A0%EC%9E%90%EC%9D%BC%20%EC%8A%A4%ED%94%84%EB%A6%B0%ED%8A%B8%20%EC%97%B0%EA%B3%84%3Cbr%2F%3E(Agile%20%26%20Scrumban%20Execution)%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20P1%20--%3E%20P2%0A%20%20%20%20P2%20--%3E%20P3%0A%20%20%20%20P1%20--%3E%20P4%0A%20%20%20%20P3%20--%3E%20P4%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=l('<ol><li><strong>사업 및 프로젝트 관리 (Business &amp; PM Governance)</strong>: <ul><li>부실 수주 차단(Go/No-Go), 선금 50% 확보, 4대 서명(Sign-off) 관리, 지체상금 및 외주 위장도급 리스크 차단, 100% 잔금 회수 행정 체계.</li></ul></li><li><strong>AI 개발 생명주기 (Empasy AI-SDLC)</strong>: <ul><li>기획부터 배포까지 5단계(요구사항 구체화 ➔ 명세 우선 아키텍처 ➔ 에이전트 협업 구현 ➔ 4단계 회귀 검증 ➔ 무인 배포) 엔지니어링 표준.</li></ul></li><li><strong>표준 산출물 &amp; 122종 실전 문서 스위트 (Deliverables Suite)</strong>: <ul><li>공공기관, 금융권, 대기업 감사를 무결함으로 통과할 수 있는 122종의 오피스(Word, PPT, Excel, PDF) 및 마크다운 원본 템플릿.</li></ul></li><li><strong>애자일 스프린트 연계 (Agile &amp; Scrumban Execution)</strong>: <ul><li>거시적 마일스톤(WBS)을 일상적인 1~2주 스프린트로 세분화하고, Git Flow 및 이슈 트래킹 기반으로 매일 유기적으로 구동되는 실행 문화.</li></ul></li></ol><hr><h2 id="_2-8대-핵심-역할별-원클릭-퀵-점프-매트릭스" tabindex="-1">2. 8대 핵심 역할별 원클릭 퀵 점프 매트릭스 <a class="header-anchor" href="#_2-8대-핵심-역할별-원클릭-퀵-점프-매트릭스" aria-label="Permalink to “2. 8대 핵심 역할별 원클릭 퀵 점프 매트릭스”">​</a></h2><p>자신의 역할에 맞추어 필수 가이드와 양식을 즉시 확인하십시오.</p><table tabindex="0"><thead><tr><th style="text-align:left;">역할</th><th style="text-align:left;">담당 직무</th><th style="text-align:left;">필수 확인 가이드</th><th style="text-align:left;">작성 및 관리 필수 서식 (122종 템플릿)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>영업 / 사업대표</strong></td><td style="text-align:left;">수주 타당성 검토, RFP 분석, 견적 산출, 계약 체결, 잔금 회수</td><td style="text-align:left;"><a href="./presales-ai-playbook">사전영업 플레이북</a><br><a href="./enterprise-project-lifecycle">라이프사이클 총괄</a></td><td style="text-align:left;">NDA, Go/No-Go 심의표, TCO 원가계산서, 표준계약서, 기성/준공 대금청구 공문</td></tr><tr><td style="text-align:left;"><strong>총괄 PM / PO</strong></td><td style="text-align:left;">일정 통제(WBS), 마일스톤, 4대 서명 확보, 변경 통제, 감리 대응</td><td style="text-align:left;"><a href="./enterprise-action-items-guide">28대 실행 가이드(SOP)</a><br><a href="./enterprise-business-documents">표준 문서 체계 가이드</a></td><td style="text-align:left;">사업수행계획서, WBS 마스터, Scope Freeze 합의서, 주간/월간보고, CR Form, 최종 검수확인서</td></tr><tr><td style="text-align:left;"><strong>시스템 아키텍트</strong></td><td style="text-align:left;">시스템 구조 설계, 네트워크/망분리, 표준 DDL/API 규격 확정</td><td style="text-align:left;"><a href="./ai-sdlc-02-architecture">명세 우선 아키텍처 가이드</a><br><a href="./ai-driven-development">AI-SDLC 총괄</a></td><td style="text-align:left;">시스템 아키텍처 설계서(SAD), 개발 표준 정의서, 개발 환경 정의서, 컴포넌트 설계서</td></tr><tr><td style="text-align:left;"><strong>백엔드 / 프론트 개발</strong></td><td style="text-align:left;">에이전트 협업 코딩, 인터페이스 구현, 단위 테스트, 무인 빌드</td><td style="text-align:left;"><a href="./ai-sdlc-03-implementation">에이전트 협업 구현 가이드</a><br><a href="./ai-sdlc-prompt-recipes">실전 프롬프트 치트시트</a></td><td style="text-align:left;">테이블 정의서(ERD), Canonical API 명세서, 단위 테스트 시나리오 및 디버깅리스트</td></tr><tr><td style="text-align:left;"><strong>QA / 테스트 엔지니어</strong></td><td style="text-align:left;">4단계 피라미드 테스트, BDD 검증, 시큐어코딩 진단, UAT 검증</td><td style="text-align:left;"><a href="./ai-sdlc-04-testing">테스트 자동화 가이드</a><br><a href="./ai-sdlc-01-requirements">기획 및 요구사항 가이드</a></td><td style="text-align:left;">통합 테스트 계획서/시나리오, SW 개발보안 49개 점검표, 사용자 인수 테스트(UAT) 확인서</td></tr><tr><td style="text-align:left;"><strong>DevOps / 보안 관리</strong></td><td style="text-align:left;">인프라 구성, CI/CD 무인 배포, 카나리 롤아웃, 보안 침해사고 대응</td><td style="text-align:left;"><a href="./ai-sdlc-05-review-deploy">코드 검토 및 배포 가이드</a><br><a href="./enterprise-business-documents">표준 문서 체계 가이드</a></td><td style="text-align:left;">시스템 배포 및 롤백 런북, 컷오버 이행계획서, 시스템 설치계획서, 개인정보 유출 신고서</td></tr><tr><td style="text-align:left;"><strong>경영지원 / 법무</strong></td><td style="text-align:left;">입찰 서류, 선금/계약 보증보험 발행, 하도급 승인, 외주/프리랜서 계약</td><td style="text-align:left;"><a href="./enterprise-business-documents">표준 문서 체계 가이드</a><br><a href="./enterprise-document-templates">서식 다운로드 센터</a></td><td style="text-align:left;">선금 신청서, 하도급 사전승인 신청서, 외주 도급계약서, 프리랜서 용역계약서</td></tr><tr><td style="text-align:left;"><strong>발주처 / 고객사 현업</strong></td><td style="text-align:left;">요구사항 확정, 중간 점검, UAT 인수 검사, 최종 준공 검사</td><td style="text-align:left;"><a href="./enterprise-project-lifecycle">라이프사이클 총괄</a><br><a href="./enterprise-business-documents">표준 문서 체계 가이드</a></td><td style="text-align:left;">Scope Freeze 합의서, 화면설계 승인서, UAT 확인서, 최종 검수 완료 확인서 및 인수증</td></tr></tbody></table><hr><h2 id="_3-사업-전-주기-6단계-라이프사이클-로드맵" tabindex="-1">3. 사업 전 주기 6단계 라이프사이클 로드맵 <a class="header-anchor" href="#_3-사업-전-주기-6단계-라이프사이클-로드맵" aria-label="Permalink to “3. 사업 전 주기 6단계 라이프사이클 로드맵”">​</a></h2>',7)),(a(),r(o,null,{default:e(()=>[n(s,{id:"mermaid-207",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20P0%5B%22Phase%200%3A%20%EC%82%AC%EC%A0%84%EC%98%81%EC%97%85%3Cbr%2F%3E(Pre-sales)%22%5D%20--%3E%20P1%5B%22Phase%201%3A%20%EC%B0%A9%EC%88%98%20%26%20%EB%B6%84%EC%84%9D%3Cbr%2F%3E(Inception%20%26%20SRS)%22%5D%0A%20%20%20%20P1%20--%3E%20P2%5B%22Phase%202%3A%20%EC%84%A4%EA%B3%84%20%26%20%EA%B7%9C%EA%B2%A9%3Cbr%2F%3E(Architecture)%22%5D%0A%20%20%20%20P2%20--%3E%20P3%5B%22Phase%203%3A%20%EA%B5%AC%ED%98%84%20%26%20%EA%B3%B5%EC%A0%95%3Cbr%2F%3E(Implementation)%22%5D%0A%20%20%20%20P3%20--%3E%20P4%5B%22Phase%204%3A%20%ED%92%88%EC%A7%88%20%26%20%EA%B0%90%EB%A6%AC%3Cbr%2F%3E(Testing%20%26%20Audit)%22%5D%0A%20%20%20%20P4%20--%3E%20P5%5B%22Phase%205%3A%20%EC%98%A4%ED%94%88%20%26%20%EC%A0%95%EC%82%B0%3Cbr%2F%3E(Release%20%26%20Settlement)%22%5D%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[i(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=l('<h3 id="phase-0-사전영업-및-제안-지원-pre-sales" tabindex="-1">[Phase 0] 사전영업 및 제안 지원 (Pre-sales) <a class="header-anchor" href="#phase-0-사전영업-및-제안-지원-pre-sales" aria-label="Permalink to “[Phase 0] 사전영업 및 제안 지원 (Pre-sales)”">​</a></h3><ul><li><strong>목표</strong>: 부실 수주를 원천 차단하고 수주 성공률과 마진율을 극대화합니다.</li><li><strong>핵심 활동</strong>: Go/No-Go 심의(70점 기준), NDA 체결, RFP 요구사항 분해, 3개년 TCO 원가 계산, 기술 제안서 작성, PoC 실증, 심사위원 Q&amp;A 방어.</li><li><strong>바로가기</strong>: <a href="./presales-ai-playbook">영업 지원 및 제안 단계 실무 플레이북</a></li></ul><h3 id="phase-1-프로젝트-착수-및-요구사항-분석-inception-analysis" tabindex="-1">[Phase 1] 프로젝트 착수 및 요구사항 분석 (Inception &amp; Analysis) <a class="header-anchor" href="#phase-1-프로젝트-착수-및-요구사항-분석-inception-analysis" aria-label="Permalink to “[Phase 1] 프로젝트 착수 및 요구사항 분석 (Inception &amp; Analysis)”">​</a></h3><ul><li><strong>목표</strong>: 과업 범위를 동결하고 초기 자금을 안전하게 확보합니다.</li><li><strong>핵심 활동</strong>: 착수계 및 사업수행계획서 제출, 착수보고회, 선금(30~50%) 신청 및 보증보험, 하도급 사전승인, SRS v1.0 및 RTM 확정, <strong>과업 범위 확정 합의서(Scope Freeze Sign-off)</strong>.</li><li><strong>바로가기</strong>: <a href="./ai-sdlc-01-requirements">01단계 기획 및 요구사항 구체화 실무 가이드</a></li></ul><h3 id="phase-2-명세-우선-아키텍처-및-상세-설계-design-spec" tabindex="-1">[Phase 2] 명세 우선 아키텍처 및 상세 설계 (Design &amp; Spec) <a class="header-anchor" href="#phase-2-명세-우선-아키텍처-및-상세-설계-design-spec" aria-label="Permalink to “[Phase 2] 명세 우선 아키텍처 및 상세 설계 (Design &amp; Spec)”">​</a></h3><ul><li><strong>목표</strong>: 코딩 시작 전 데이터 모델과 API 계약을 확정하여 프론트-백엔드 병목을 제거합니다.</li><li><strong>핵심 활동</strong>: 화면 UI/UX 상세 스토리보드, 메뉴 정보구조도(IA), 시스템 아키텍처(SAD), PostgreSQL 표준 DDL, Canonical API 명세서, <strong>화면 UI 설계 승인서(Design Freeze Sign-off)</strong>.</li><li><strong>바로가기</strong>: <a href="./ai-sdlc-02-architecture">02단계 명세 우선 아키텍처 및 DDL/API 설계 가이드</a></li></ul><h3 id="phase-3-ai-협업-코딩-및-공정-통제-implementation-control" tabindex="-1">[Phase 3] AI 협업 코딩 및 공정 통제 (Implementation &amp; Control) <a class="header-anchor" href="#phase-3-ai-협업-코딩-및-공정-통제-implementation-control" aria-label="Permalink to “[Phase 3] AI 협업 코딩 및 공정 통제 (Implementation &amp; Control)”">​</a></h3><ul><li><strong>목표</strong>: 계획 대비 실적 공정률을 엄격히 통제하고 사양 변경을 공식적으로 제어합니다.</li><li><strong>핵심 활동</strong>: 주간/월간 진척 보고, WBS 마스터 및 마일스톤 추적, 비용 관리대장, 요구사항 변경 통제(CR Form), 기성금(중도금 40%) 검수 신청.</li><li><strong>바로가기</strong>: <a href="./ai-sdlc-03-implementation">03단계 에이전트 협업 코딩 및 자율 구현 가이드</a></li></ul><h3 id="phase-4-품질-검증-보안-및-감리-대응-testing-audit" tabindex="-1">[Phase 4] 품질 검증, 보안 및 감리 대응 (Testing &amp; Audit) <a class="header-anchor" href="#phase-4-품질-검증-보안-및-감리-대응-testing-audit" aria-label="Permalink to “[Phase 4] 품질 검증, 보안 및 감리 대응 (Testing &amp; Audit)”">​</a></h3><ul><li><strong>목표</strong>: 공인 감리 적격 판정을 획득하고 고객사의 공식 인수 서명을 이끌어냅니다.</li><li><strong>핵심 활동</strong>: 단위/통합 테스트 계획 및 시나리오 수행, 결함 추적 디버깅리스트, 행안부 SW 개발보안 49개 점검, 오픈소스(OSS) 라이선스 검증, 3자 감리 지적사항 조치, <strong>사용자 인수 테스트(UAT Sign-off)</strong>.</li><li><strong>바로가기</strong>: <a href="./ai-sdlc-04-testing">04단계 테스트 자동화 및 4단계 오류 자동 수정 가이드</a></li></ul><h3 id="phase-5-시스템-오픈-최종-검수-및-정산-release-settlement" tabindex="-1">[Phase 5] 시스템 오픈, 최종 검수 및 정산 (Release &amp; Settlement) <a class="header-anchor" href="#phase-5-시스템-오픈-최종-검수-및-정산-release-settlement" aria-label="Permalink to “[Phase 5] 시스템 오픈, 최종 검수 및 정산 (Release &amp; Settlement)”">​</a></h3><ul><li><strong>목표</strong>: 무중단 컷오버를 완수하고 최종 잔금(30%)을 100% 회수하며 1년 무상 보증을 개시합니다.</li><li><strong>핵심 활동</strong>: 컷오버 배포 계획서 및 롤백 런북, 데이터 이관 대사표(오차 0원), 사용자/운영자 매뉴얼, 교육훈련 실시, <strong>최종 검수 완료 확인서(Acceptance Sign-off)</strong>, 준공 대금 청구 공문, 하자보수보증보험증권 발행, 유지보수 SLA 협약.</li><li><strong>바로가기</strong>: <a href="./ai-sdlc-05-review-deploy">05단계 코드 검토 및 무인 배포 가이드</a></li></ul><hr><h2 id="_4-공식-산출물-및-서식-다운로드-센터-122종" tabindex="-1">4. 공식 산출물 및 서식 다운로드 센터 (122종) <a class="header-anchor" href="#_4-공식-산출물-및-서식-다운로드-센터-122종" aria-label="Permalink to “4. 공식 산출물 및 서식 다운로드 센터 (122종)”">​</a></h2><p>프로젝트 현장에서 즉시 편집하여 사용할 수 있는 122종의 오피스 원본 서식과 마크다운 템플릿을 제공합니다.</p><div class="tip custom-block"><p class="custom-block-title">122종 통합 다운로드 센터 안내</p><ul><li><strong><a href="./enterprise-document-templates">표준 문서 양식 통합 다운로드 센터 바로가기</a></strong></li><li><strong>제공 패키지 옵션</strong>: <ol><li><strong>전체 통합 마스터팩 (<code>Empasy_Total_Master_Pack.zip</code>, 약 51.6 MB)</strong>: 엠파시 표준 서식 46종 + 실전 PM Suite 76종 등 전 122종 총괄 패키지</li><li><strong>실전 프로젝트 관리 스위트 (<code>Empasy_PM_Suite_Templates.zip</code>, 약 50.4 MB)</strong>: PMBOK 기반 76종 실무 서식 및 관리자 교육 교재 전용팩</li><li><strong>핵심 표준 서식팩 (<code>Empasy_Methodology_All_Templates.zip</code>, 약 925 KB)</strong>: 단계별 계약·행정 46종 초경량 고속 다운로드팩</li></ol></li></ul></div><hr><h2 id="_5-단계별-실행-항목-가이드-28대-action-items-sop" tabindex="-1">5. 단계별 실행 항목 가이드 (28대 Action Items SOP) <a class="header-anchor" href="#_5-단계별-실행-항목-가이드-28대-action-items-sop" aria-label="Permalink to “5. 단계별 실행 항목 가이드 (28대 Action Items SOP)”">​</a></h2><p>프로젝트 실무자가 단계마다 &#39;무엇을, 어떤 순서로, 어떤 도구로 실행하고, 어떻게 통과 판정하는지&#39;를 명시한 표준 운영 절차서입니다.</p><ul><li><strong><a href="./enterprise-action-items-guide">단계별 실행 항목 및 실무 실행 가이드 (SOP) 전문 보기</a></strong><ul><li>1단계(사전영업): A1.0 ~ A1.6 (7개 실행 항목)</li><li>2단계(착수/분석): A2.1 ~ A2.5 (5개 실행 항목)</li><li>3단계(설계/규격): A3.1 ~ A3.4 (4개 실행 항목)</li><li>4단계(구현/개발): A4.1 ~ A4.4 (4개 실행 항목)</li><li>5단계(품질/감리): A5.1 ~ A5.4 (4개 실행 항목)</li><li>6단계(배포/정산): A6.1 ~ A6.4 (4개 실행 항목)</li></ul></li></ul><hr><h2 id="_6-애자일-프로세스-및-공학-워크플로우와의-연계" tabindex="-1">6. 애자일 프로세스 및 공학 워크플로우와의 연계 <a class="header-anchor" href="#_6-애자일-프로세스-및-공학-워크플로우와의-연계" aria-label="Permalink to “6. 애자일 프로세스 및 공학 워크플로우와의 연계”">​</a></h2><p>본 사업 방법론의 거시적 마일스톤(WBS)을 일상적인 개발팀 단위에서 매주 기동하기 위한 구체적인 스프린트 운영 및 엔지니어링 문화는 독립된 <strong><a href="/agile/">애자일 프로세스</a></strong> 메뉴를 통해 관리됩니다:</p><ul><li><strong><a href="/agile/scrumban">애자일 &amp; 스크럼반 운영</a></strong>: 스크럼반 하이브리드 보드 운영, WIP 제한, 데일리 스크럼, 스토리 포인트 산정</li><li><strong><a href="/agile/gitFlow">개발 공학 워크플로우</a></strong>: Git Flow 브랜치 모델, Git 커밋 로그 컨벤션, 이슈 작성 규칙</li><li><strong><a href="/agile/xp_scrum_kanban">방법론 비교 및 용어사전</a></strong>: XP, 스크럼, 칸반 비교 및 애자일 표준 용어집</li></ul>',24))])}const u=d(p,[["render",A]]);export{B as __pageData,u as default};
